// 原始下标仅用于定位已完整阅读的固定快照；执行器只按 ID 写回。
const fs = require('fs');
const ROOT = 'D:/桌面/办公软件/17.探域科技AI自动配置';
const BACKUP = 'D:/备份文件夹/探域问答审核-20260905';
const cards = require(BACKUP+'/snapshot-1788589471551.json').cards.data.results;
const edits = new Map();
const body = c => (c.content||[]).map(x=>x.content).join('\n');
const current = i => edits.get(i)?.after || cards[i];
function change(i, patch, reason) {
  if (!cards[i]) throw Error('错误下标 '+i);
  const old = edits.get(i);
  edits.set(i,{index:i,id:cards[i].id,before:cards[i],after:{...current(i),...patch},reasons:[...(old?.reasons||[]),reason]});
}
function q(i) { return body(cards[i]).match(/^Q:(.*)/)?.[1]?.trim() || cards[i].title || '商品使用咨询'; }
function qa(ids, answer, reason, question) {
  for (const i of Array.isArray(ids)?ids:[ids]) change(i,{content:[{content:`Q:${question||q(i)}\nA:${answer}`}]},reason);
}
function replace(i, from, to, reason) {
  const txt=body(current(i));
  if (!txt.includes(from)) throw Error('原文未匹配 '+i+' '+from);
  change(i,{content:[{content:txt.replaceAll(from,to)}]},reason);
}
function off(ids,reason) { for(const i of ids) if(current(i).ifOpen) change(i,{ifOpen:false},reason); }
const medical='需要先由医生确定是否需要吸氧、供氧方式、流量和每日时长。请提供医生明确的用氧要求及准备购买或正在使用的型号，我们再核对设备是否满足要求；不能仅按疾病名称、年龄或单次血氧读数推荐档位。';
const adjust='请按医生为您制定的用氧处方设置流量和时长，不要按通用血氧区间自行加减档，也不要以“越高越好”或感觉舒服作为调节标准。如当前用氧效果不佳或出现不适，应及时联系医生；严重气促、胸痛、意识异常等情况请立即拨打120，勿等待换机或调档测试。';
qa([19,481],'每次吸多久、每天吸几次应按医生为您制定的用氧方案执行，不能统一建议早中晚各30分钟。没有明确用氧建议时，请先由医生评估是否需要吸氧。设备可连续工作的时长还需核对具体型号说明书。','撤除统一吸氧时长处方');
qa([43,479,480,482,510,511,512,514,515,516,517,518,523,524,526,836,979,1043,1065],adjust,'撤除血氧数值直接映射档位/时长的自动医疗指导');
qa([64,938,939,940,941,942,969,970,992,993,995,996,997,998,999,1000,1001,1007,1008,1009,1015,1025,1026,1027,1028,1029,1030,1031,1032,1033,1034,1035,1036,1037,1038,1058,1059,1060],medical,'撤除按疾病/年龄直接推荐升数的医疗处方');
qa([92,453,725,726,728,729,814],'吸氧后血氧未改善，不能直接判断机器正常，也不能据此让您升级更大流量机型。请保持医生规定的用氧方案，核对测量方法，并提供机器型号、当前设置及报警情况交人工排查；不要自行拆除过滤器或改装气路。若明显不适或情况加重，请及时就医；严重气促、胸痛或意识异常请立即拨打120。','不以升级购买替代病情评估和故障诊断');
qa([23,24,25,26,27,477],'机器出口氧浓度和人体实际吸入氧浓度不是同一指标；实际吸入情况还受供氧接口、呼吸状态等因素影响，不能用固定换算表或简易公式准确推算个人吸入浓度。请按照医生规定的供氧方式和流量选用设备，不能因混入空气就判断某一档位一定安全。','撤除自造吸入氧浓度公式和放心用的保证');
qa(28,'血氧饱和度不能用来直接判断机器出口氧浓度。读数还受身体状况和测量条件影响；机器是否达标应按该型号说明书的额定工况，用适用的测氧设备检测。若血氧持续低于医生给您的目标或伴有不适，请及时就医。','区分设备参数与人体读数');
qa([205],'请按该血氧仪说明书规定的测量方式和使用时长操作，等读数稳定后记录。普通指夹式产品不能直接当作长期连续监护设备使用；夹持不适、皮肤异常时应取下检查。是否需要连续监测，请咨询医生。','撤除无依据的1分钟/30分钟坏死阈值');
qa([207,209,227,228],'血氧仪读数需结合症状和医生设定的个人目标判断，不能仅靠一次读数诊断缺氧或决定吸氧浓度。测量时保持安静、手指温暖，按说明书佩戴并等待读数稳定；可复测确认，但不要用多次平均值掩盖持续低读数。持续异常或不适请及时就医，严重气促、胸痛或意识异常请立即拨打120。','血氧测量按FDA资料纠正，不给通用治疗阈值');
qa(208,'波形表示设备检测到的脉搏信号，不能据此判断心脏健康，也不能排除疾病。请结合血氧、脉率、症状及医生评估；如有持续不适，应及时就医。','撤除波形等于心脏健康的推断');
qa([229,231],'PI是血氧仪显示的灌注相关指标，不能单独用于判断心肺健康或诊断疾病，也不宜把一个通用区间当作所有人的正常标准。请结合该型号说明书、测量条件及医生评估理解读数。','撤除PI通用正常范围和诊断推断');
qa(230,'血氧仪夹在非人体物品上出现数值，不代表物品有血氧，也不能证明仪器性能正常。请只按说明书在适用人体部位测量；如对准确性有疑问，请提供型号及测量经过，由人工协助核实。','撤除非人体读数可以证明仪器正常');
qa(525,'血氧仪通常显示的是血氧饱和度（SpO₂），不是制氧机的出氧浓度，也不是血液中氧气总量。单次读数不能替代医生诊断，应结合测量条件、症状和个人用氧方案判断。','澄清血氧/出氧浓度概念');
qa([1003,1021],'不建议通过自行快走6分钟或故意增加运动量来判断是否缺氧、是否需要制氧机。请由医生评估是否需要检查或规范的运动试验；静息或活动时有明显不适，应及时就医。','撤除自行运动诱发缺氧测试');
qa([874,954,968,1002,1044],medical,'撤除以病情严重程度直接选1/2/3/5L');
qa([124,1055],'儿童是否适合雾化，应先由医生评估，并核对设备及雾化组件说明书的适用人群。药物、剂量和使用方法须遵医嘱，不能统一按3岁或6岁划线，也不要自行调小雾化档位代替处方。使用时需成人照看。','撤除冲突的儿童年龄限制及自行调药/档建议');
qa(1056,'婴儿是否需要吸氧、使用何种接口、流量和监测方式，必须由儿科医生制定方案，不能统一按0.1—0.15L/min估算。请提供医生明确的设备要求，再核对具体机型是否适用；不要自行购买后试调档位。','撤除婴儿固定流量处方');
qa(233,'雾化杯加药量、是否需要稀释及每次使用时长请遵医嘱，并遵守该雾化杯标示的容量范围。刻度线不是所有药物的统一加药剂量，不要自行加满或随意增加药量。','撤除加药到刻度线即正确的提示');
qa([129,239],'雾化功能是否适合治疗，需要核对具体型号的注册用途、雾化性能及医生要求。不能把保健机的雾化功能直接当作医用雾化设备的替代，也不应承诺吸收更快或疗效更好。请提供型号和医生要求后再确认。','撤除未证实治疗效果和医用替代');
qa(252,'制氧和雾化能否同时开启，须按具体型号说明书确认。正在按医嘱持续吸氧的人，不要为雾化自行中断供氧；请先向医生确认安排，再按对应设备操作。','撤除统一先雾化后吸氧');
qa([212,234],'医院与家用雾化设备不能仅按出雾大小比较效果。请核对雾化器型号、适用药物和说明书参数，并遵医嘱使用；不要为了模仿医院出雾量自行加药或调节治疗方案。','撤除医院大流量只是提高效率的猜测');
qa(506,'吸氧并非越多越好，风险与吸入氧浓度、时长及个人病情有关，不能用“未超过24小时就不会氧中毒”等单一阈值保证安全。请按医生的用氧方案执行，有不适及时就医。','撤除氧中毒绝对安全阈值');
qa(890,'是否需要长期吸氧取决于病情，不应简单理解为“上瘾”或“完全没有风险”。请遵医嘱使用，不要自行延长时长或增加流量；是否减量或停氧也应由医生评估。','撤除吸氧无风险保证');
qa([491,1005,1046,1047,1048],'呼吸机或气管切开患者能否连接制氧机，应由医生确认，并同时核对呼吸机、制氧机及连接组件的说明书。没有通用“至少5L”或任意三通都兼容的规则。请提供双方完整型号及医生规定的流量，不要自行改装接口、堵塞呼气孔或试接。','撤除通用5L门槛和任意联用；依据ResMed兼容性说明');
qa(1006,'吸氧管或接头不能只凭看起来能插上就认定兼容。请提供制氧机、呼吸机及接口的完整型号或清晰照片，核对说明书指定组件后再连接，不建议自行试接或改装。','避免未确认接口直接试用');
qa(1051,'疑似一氧化碳中毒属于急症，请立即拨打120，并在确保自身安全的前提下离开危险环境。不要等待购买家用制氧机，也不要依靠家用设备自行治疗。后续是否需要居家用氧及设备要求，由接诊医生决定。','保留紧急就医，撤除康复统一5L选型');
qa([904],'宠物是否需要吸氧、流量和时长应由兽医评估，不能统一建议5L或每次30分钟。请先取得兽医明确的设备要求，再核对机型和接口是否符合；急性呼吸困难应尽快联系急诊兽医。','撤除动物固定氧疗处方');
qa([15,14],'可以先了解是不愿意吸氧，还是鼻吸管佩戴不适。若医生已要求吸氧，请先与医生讨论原因和替代接口；鼻吸管与面罩不能随意互换，尤其应确认脉冲供氧设备的兼容要求，不应仅因面罩感觉柔和就自行更换。','保留已批准问题，去掉面罩普遍更柔和且可随意替换');
qa([418,419,1023],'吸氧时刺激、呛鼻或不舒服，不能仅凭描述认定为干燥或排除机器故障。请提供机器型号、所用接口及是否有异味、报警等情况。不要自行调低医嘱流量或改装湿化装置；持续不适应咨询医生，明显气促或症状加重请及时就医。','去掉无检测正常结论和自行调档');
qa([564,582,758,778,182],'鼻吸管和面罩的适用条件不同，不能仅凭感觉气流更柔和就互换，也不能保证换面罩后效果不变。请先核对具体机型、供氧方式及接口说明书，并按医生要求选择。','撤除面罩普遍兼容及效果保证');
// 安全排查：只保留无需拆机的观察步骤，不远程下检测结论。
const fault='请先提供完整型号、显示或报警代码及故障出现经过，可补充机器外观、接口和使用环境照片。保持进出风口畅通，按该型号说明书检查可由用户操作的外部连接；不要拆机、去掉过滤器运行或把档位调到最大试机。异常持续时请申请人工售后核实。依赖持续供氧者应按医生预先制定的备用供氧方案处理，不要等待排查而中断必需用氧。';
qa([35,50,52,214,470,476,753,807,808],fault,'撤除无滤芯/最大档/绕过气路等未经型号确认的测试');
qa([31,32,47,48,607,608,609,610,611,612,613,621,622,685,687,688,689],fault,'故障码含义依赖型号，不再给跨型号拆卸/最大档测试');
qa([219,813],'请不要用明火、香烟、火星或助燃实验测试氧气。氧气会助燃，可能造成火灾或烧伤。若怀疑出氧浓度异常，请提供机器型号、当前设置和报警情况，由人工安排按该型号要求使用适用仪器检测。','禁止助燃测试，不再提供坚持测试时的做法');
qa([583,606],'不建议把正在使用的鼻吸管插入水中来判断制氧机是否正常，冒泡不能证明氧浓度达标，还可能污染管路。请提供型号、设置和报警情况，按说明书检查外部连接；仍有疑问请申请人工检测。','去掉水中冒泡作为合格测试');
qa([602,604],'湿化瓶冒泡只反映气流经过水，不能证明出口氧浓度或整机性能正常。请提供型号、设置及异常表现；怀疑浓度问题时需按该型号要求用适用测氧仪检测。','不以冒泡证明机器合格');
qa([450,763,765,782,784],'运行中的散热部位可能发热，但不能仅凭手摸或一个通用温度值保证正常。请保持通风、不覆盖机器；如有烫伤风险、焦糊味、冒烟或持续报警，应在安全前提下停用断电并联系人工售后。依赖持续供氧者应使用医生预先安排的备用方案。','撤除60度均正常等绝对判断');
qa([785,787],'发现明显异味时，请先确认来自包装、吸氧管还是机器，并提供型号和出现时机。不要靠连续运行数小时或数天来“散味”并继续吸入。若有焦糊味、冒烟、异常发热或身体不适，请在安全前提下停用断电，及时联系人工；明显身体不适应就医。','撤除新机异味一定正常及长时间运行消味');
qa(246,'如设备冒烟、起火或存在触电危险，请先保护人员安全，不要继续使用或急于打包寄回；有火情请拨打119，人员不适或受伤请拨打120。在安全前提下停止使用并联系人工售后，保留现场及设备情况，后续检测和运输方式需确认安全后安排。','内部事故运费话术改为面向买家的安全处置');
qa(605,'先停止使用并拔下电源。只有说明书明确允许用户更换、且无需拆开机壳的保险丝，才可按规定型号和额定值更换；不确定位置或规格时请联系人工售后，不要带电操作或用其他物品代替保险丝。','补充断电和用户可维护边界');
qa(816,'电源接口松动、接触不良不能直接判断为正常，请停止反复晃动或强行插拔。断电后检查外部连接是否到位，并提供型号及接口照片；若仍松动、发热或有火花，请停用并申请人工售后。','撤除电源松动放心使用');
qa([166,328,330,500,732],'请先确认吸氧管包装上标明的是一次性使用还是可重复使用。一次性管路不要清洗后重复使用；可重复使用管路的清洗、消毒和更换周期应按其说明书执行，不统一建议用醋、洗洁精或酒精。材质与耐受方式需核对具体配件。','统一一次性/可复用边界，撤除自配清洗法和材质猜测');
qa([668,669,752],'过滤器能否水洗必须看具体型号说明书和过滤器标识。没有明确可水洗说明时，不要浸洗后继续使用；已经进水请停止使用该过滤器并联系人工核对更换方式，不能以晾干72小时保证可用。','撤除不支持水洗仍教清洗/干燥保证');
qa([710,711],'不建议自行购买通用管路剪裁改装。请提供设备型号、配件名称或照片，核对尺寸与兼容性后选用配件；不方便拍照时可提供铭牌型号和原配件标识。','撤除未知规格通用改装');
qa(691,'维修后显示时间变化，需要结合该型号计时功能和维修记录核实。计时归零不代表设备变成新机，也不代表历史使用和磨损消失。请提供订单及维修单号，由人工确认具体更换部件和计时变化原因。','不以清零将维修机描述为新机');
qa([692,721],'维修更换了哪些部件，应以实际检测和维修记录为准，不能预先承诺全部换新。请提供订单或维修单号，由人工核对已做项目、检测结果和相应保修安排。','撤除未经记录的全部换新结论');
qa(616,'维修后长期未取回的设备，需要人工核实维修记录、联系情况和保管安排。请提供订单或维修单号确认；不能直接以超过一个月为由认定放弃或告知已经报废。','撤除自动弃置/报废威胁');
qa(656,'请提供订单或维修单号，由人工核查设备当前状态和领取安排。未核实前不能认定客户失联、已放弃设备或设备已报废。','撤除未经核实的弃置设备结论');
// 订单与售后状态不能作为固定事实。保留可执行的信息收集，不伪造已经操作。
qa([55,172,174,175],'请提供需要开票的订单及发票类型，由人工核实开票状态和所需资料；请勿发送密码或验证码。提交资料不等于已经开票，是否开具、发送方式及预计时间以实际处理记录为准。','撤除已登记/已催办/系统故障等固定进度');
qa([57,58,59,178,179],'请说明需要个人或单位发票、普通或专用发票，并提供对应订单。具体开票资格、必要资料及授权要求请由人工财务核实；不把“专票只能公司对公司”或必须盖章说成通用法律要求，也不要求无关个人信息。','撤除未经核实的税法结论，保留人工财务确认');
qa([61,153,163,377,430,431,432],'请提供对应订单、活动页面或原承诺记录，由人工核实赠品资格、是否已登记及发货状态。未查询记录前，不能确认已经登记、已经寄出或承诺补发时间。','赠品状态不再虚构已登记/已联系/已发');
qa([62,103,116],'如果收到的商品或配件与订单不一致，请提供订单、外包装面单及收到物品的照片，并说明缺少或错发什么。由人工核对订单与出库记录后确认处理方案；不要先取消售后，也不能在核实前承诺补发或补偿。','错漏发先核实，不先要求撤销售后');
qa(63,'请先提供对应订单和问题说明。只有确需核对收件或补寄信息时，再在平台会话中提供必要的收件信息；不要发送身份证、密码、验证码或与处理无关的个人资料。','减少不必要个人信息收集');
qa(65,'如需电话沟通，请在平台会话中向人工客服确认便于联系的号码和时间。不要直接假定已有号码正确，也不要发送验证码。','消除号码指代不明和默认已掌握信息');
qa([67,68,74,76],'请通过该订单的售后入口提交与实际情况一致的退款或退货申请；是否已发货、能否拦截及处理进度，需要人工核实订单和物流记录。不要为了催发货而保留不需要的订单，也不应以信用受损威胁撤销售后。','撤除平台不支持/信用威胁/退款期间继续发货');
qa([73,130],'请提供订单或退回物流单号，由人工核实仓库签收及退款进度。物流显示签收不等于已经完成验货和退款，具体状态以订单售后页及实际处理记录为准；不能预先承诺1—2天到账。','撤除已催退款和未核实签收状态');
qa([75,101],'能否拦截需要核实当前物流节点，请提供订单，由人工向承运方确认。未取得物流结果前，不能承诺已经拦截、一定成功或不能再次配送。','撤除已经拦截等假状态');
qa([83,89,93,95],'售后原因请按实际情况填写：有质量异常就如实描述问题，单纯不需要则选择相应无理由选项。不要为了处理速度或商家考核修改成不真实的原因。退换处理及费用由人工结合订单和核实结果确认。','取消诱导修改真实退换货原因');
qa([84,85,86],'可以按实际需求在订单售后入口申请退货或换货，并如实填写原因。请提供订单及具体问题，由人工核实处理条件；不应为了所谓更快通过而改成与实际情况不符的理由。','取消售后路径速度暗示和原因诱导');
qa([90,94,96,364],'您希望退货、换货还是维修，请先明确选择，再由人工核对订单及当前售后申请。未经您确认，不应擅自关闭换货、改成退货，也不能预先声称已登记、已批准或保证处理完成时间。','退换操作须真实并尊重买家选择');
qa([98,99],'配送异常原因需要查看真实物流记录并向承运方核实，不能直接认定您被拉黑、拒接电话或不配合。请提供订单或物流单号及遇到的问题，由人工协助查询。','撤除对买家的无依据归责');
qa([20,21,100,107,127,427],'请提供对应订单和收货地区，由人工核实仓库处理及物流状态。是否已加急、当天能否发出和预计到达时间以实际记录为准，不能在未查询前保证今天发、明天到。','撤除未查询的已加急及确定发到时间');
qa(111,'请在订单详情查看实际物流单号和最新轨迹；需要协助时可提供订单，由人工核实。未查到真实单号前，不发送“xxxxx”等占位信息，也不声称已转交处理。','清除物流占位符和假状态');
qa([112,113,637],'如物流提示地址或电话异常，请提供订单并核对订单内收件信息，由人工确认是否可修改或需联系承运方。未查询前不能认定地址错误、电话错误或包裹已退回。','不预判收件信息错误及退回状态');
qa([114,115],'更改地址或电话需要核实订单是否出库及物流是否支持修改。请在平台会话中向人工提供对应订单和需要变更的必要信息；收到实际确认前不能认为修改已经成功。','地址更改不作已完成承诺');
qa([131,132,133,134,135,614,647,717,748,749,750],'故障原因和责任需要结合实际检测记录核实，不能仅凭聊天、过滤器外观或维修次数认定设备正常或使用不当。请提供订单、设备型号和故障经过；如已有检测报告，可由人工逐项解释检测结果和后续处理方案。','撤除假检测结论和未经证实的买家责任');
qa([639,640],'过滤器变色是否影响使用，需结合型号、使用环境和说明书规定核实，不能只看颜色就保证正常或要求继续使用。请提供型号和过滤器照片，按该型号要求确认是否需要更换。','不凭颜色断言过滤性能正常');
qa([660,661,662,663,664,665,666,667],'请提供机器型号及过滤器的清晰照片，核对是否存在堵塞、受潮或安装问题。未看到实际情况前，不能说过滤器已经堵死或据此确定故障原因；也不要拆掉过滤器运行测试。','撤除以不存在的图片为依据下结论');
qa([642,653],'请提供订单或维修单号，由人工核实当前检测、报价及维修进度。未查询实际记录前，不能声称已催办、已报价或已经安排维修。','维修进度与报价以实际记录为准');
qa([530,532,548,549,550],'感谢您反馈，请说明具体问题及对应订单，必要时提供相关截图或记录。该问题需要人工核实处理，是否受理、整改或完成应以实际反馈为准，不能仅凭自动回复表示已经处理。','撤除已整改/已反馈的虚构处理记录');
qa([529,546],'您可以按真实情况反馈或评价，也可以通过平台投诉渠道反映问题。售后处理不以撤销投诉、删除差评或改好评为前提；请提供订单和诉求，由人工核实处理。','不以撤诉/改评价交换处理');
qa([541,542,623,624],'如果当前设备无法正常供氧且您依赖持续用氧，请优先按照医生预先制定的备用供氧或就医方案处理，不要等待维修而耽误用氧；严重气促、胸痛、意识异常请立即拨打120。售后需要人工核实设备及订单，不能保证故障期间供氧不中断或预先承诺处理完成时间。','危重/依赖持续供氧先安全安排，不以免责声明推责');
qa(544,'目前不提供备用机借用，因此没有可承诺的备用机消毒或寄出安排。如需要连续用氧，请事先与医生制定合适的备用供氧方案；设备售后问题可提供订单交人工核实处理。','按既有拍板政策纠正备用机矛盾');
qa(545,'对您和家人的遭遇，我们深表关切。涉及人身伤害或死亡的事件需要由人工专门核实，并配合相关调查；不能在未取得真实检测和调查结果前认定设备有责、无责或声称已提供检测报告。请保留设备及相关记录，通过平台联系人工说明情况。','撤除虚构检测和法律举证结论');
qa(625,'对您失去亲人的遭遇，我们深表慰问。请在方便时通过平台联系人工，提供相关订单和您希望处理的事项，后续按实际情况核实。','去掉丧亲场景不合适的亲昵表情');
qa([902,923],'这个问题需要人工核实处理。请在当前平台会话申请人工客服，并说明订单及具体诉求；自动回复不能代替人工受理确认。','不把话术当作已经执行转人工');
qa([365,543,654],'如果前面的说明未解决您的问题，请指出仍不清楚的地方或描述当前情况，方便人工针对性核实，不需要重复提供与问题无关的信息。','替换看聊天记录等无效指令');
qa(540,'理解您为这件事花费了时间。请说明目前未解决的问题和期望处理方式，并提供对应订单，由人工核实下一步安排。','移除轻视客户情绪的措辞');
qa(537,'可以继续说明您的问题；需要查询订单、审批或售后操作的事项，请申请人工客服确认。','不冒充正在接待的具体真人身份');
// 已有明确价格/费用人工处理政策：原位留下触发问题，不自动报价或承诺费用。
qa([60,69,70,71,104,105,136,137,138,139,140,141,142,143,154,240,241,242,243,244,245,247,249,429,436,437,533,552,615,631,633,650,652,658,699,706,742,764,802,830,835,852,858],'涉及运费、差价、扣款、补偿或维修费用，需要人工根据订单、活动和检测情况核实。请在平台会话申请人工处理；自动回复不确认应付金额、免费范围、付款方式或已经退款，不要求先提供微信收款码。','落实既有费用类人工处理政策');
qa([78,147,155,221,222,441,552,615,767,780,818,825,835,900],'是否赠送、补发、补偿或提供其他挽留方案，需要人工核对订单与原承诺后确认。请提供相关订单或沟通记录；不以取消退货、修改评价为前提，也不预先承诺赠品或金额。','撤除自动补偿/赠品挽留及领导已批准');
// 441 实际是拆电池问题，恢复为对应操作问题，不能误归入赠品。
qa([441,442,459],'请先确认便携机的完整型号和版本，再按对应说明书或由人工提供的操作教程取出电池。不要强行撬开或拆开电池外壳；如卡住、发热或鼓包，请停止操作并联系人工。','补全原只有问题/图片但无可用步骤的电池回答');
qa([892,893,894,895,896,897,898,899,905,906,907,908,909,910,911,912,929],'价格、优惠券、补贴、保价和差价申请请以当前订单结算信息及人工核实为准。请提供商品链接或对应订单并申请人工确认，不预先承诺最低价、优惠额度、补差或限时名额。','落实价格人工处理，移除占位报价/促销压单');
qa([720],'本店支持7天无理由退货，但这不等于无条件免费试用或往返运费全免。请保留商品及配件，具体退货操作和费用由人工结合订单与实际情况核实。','区分无理由退货与免费试用');
qa(737,'本店支持7天无理由退货，医疗款拆封不作为直接拒绝退货的理由。请妥善保留机器、配件和包装，并通过订单售后入口申请；具体订单及商品状态由人工核实，不预先承诺所有费用均免除。','落实已拍板医疗款拆封也支持7天无理由');
qa(362,'单个终端需要匹配主机才能使用，不能当作独立制氧机。请先提供主机和终端的完整型号，由人工确认兼容性；如不适合，可按订单实际情况申请售后，不能仅以拆封为由直接拒绝7天无理由退货。','纠正终端拆封一律不退与既有政策冲突');
qa(718,'“三包”通常指包修、包换、包退，具体适用条件应结合商品和订单核实，不能将所有产品统一套用一个法定7天/15天期限。本店已确认的服务包括7天无理由、30天内不合适换款及质量问题包退；具体申请请通过订单售后入口或人工确认。','不再错误引用统一三包法定期限');
qa(743,'家用和医用制氧机的已确认保修口径为整机1年、压缩机5年；不能扩展为所有核心部件均保5年。充电便携机另按对应政策执行，申请时请提供型号和订单核实。','压缩机5年不泛化到所有核心部件');
qa(739,'充电便携制氧机整机质保2年，电池质保1年。具体申请请提供型号及订单，是否属于保修范围由人工结合实际情况核实。','补全已有政策明确的电池例外');
// 型号与物理概念：仅修正有本店其他明确记录交叉支持的部分，不推断新参数。
qa(36,'Y300W的1—3档为额定制氧范围；4—5档为额外流量档，不保证相应氧浓度，不能把最大5档当作5L医用额定能力。具体数值请核对该版本的说明书和流量—浓度表，并按医生要求选择设备。','落实已拍板Y300W的4/5档不保证浓度');
qa(195,'MY-5C是5档调节的便携机，5档不等于持续5L/min。选型应核对具体版本的供氧方式、额定输出及医生要求，不可直接作为持续5L制氧机替代。','根据同库MY5C最高1L参数纠正5档被写成5升');
qa(194,'YS系列此处所指为8档调节，8档不等于持续8L/min。请提供完整型号和版本，再核对流量、供氧方式及续航；不要仅凭档位数字作为医用升数。','根据同库8档1.3L参数纠正8档被写成8升');
qa(216,'MY-5C、Y105/Y106和YS便携系列应分别比较供氧方式、额定输出、重量、电池配置及续航。各机型的5档、6档、8档不是持续5L、6L、8L；请提供要比较的完整型号和版本，再按医生要求核对。','纠正便携比较的档位/升数混淆');
qa(882,'Y105的脉冲供氧档位不能直接换算为持续供氧5L/min。脉冲与持续供氧的输出方式不同，不能用简易呼吸次数乘除法宣称疗效等效。需要替代现有设备时，应由医生评估，并核对具体机型说明书。','撤除错误等效5L数学和疗效结论');
qa(977,'Y106所标6档不等于持续6L/min。选择时请核对具体版本的供氧方式、额定输出、电池和适配器要求；接口外形相同不代表手机充电器或充电宝一定兼容，能否边充边用须按该版本说明书确认。','纠正6档等于6L及接口通用的危险推断');
qa(217,'脉冲供氧依赖设备对吸气的识别，不能以未感应呼吸后的自动出氧功能保证防窒息或替代监护。请核对具体型号适用条件、报警及说明书，不适合的用氧场景应由医生另行安排。','撤除自动触发防窒息保证');
qa(987,'这里介绍的是德达A1，不是A1L。现有A1资料列明无雾化、无遥控；其他功能及流量—浓度参数请核对当前商品具体版本。若要比较A1与A1L，请提供两个商品链接，不能将A1L卖点直接套到A1。','明确A1/A1L串型号，保留已有无遥控无雾化事实');
qa(918,'首次使用前，请按该版本说明书用匹配的适配器充电，并按充满提示结束；不要为了“激活电池”额外延长2—3小时充电。不同电池容量的充电时长可能不同，需按具体配置确认。','撤除额外充电激活锂电池及假支付状态');
qa(875,'Type-C只说明接口形式，不能单凭外形认定充电器或充电宝兼容。请核对具体机型要求的输入电压、电流及充电协议，使用说明书认可的适配器。','区分接口外形与供电兼容');
qa(290,'W（瓦）是功率单位，Wh（瓦时）是能量单位，两者不同。估算续航可用电池标称Wh除以设备实际平均功率W，但还受转换损耗、设置和电池状态影响，不能据此保证实际续航。','修正问题把瓦特与额定功率对比，实际应区分W/Wh','电池Wh和设备功率W有什么区别？');
qa([268,269],'W表示有功功率，VA表示视在功率，不能当作同一单位直接互换，也不是“净重”和“毛重”关系。请按机器铭牌的原单位核对电源或逆变器要求；若铭牌与说明书不一致，请提供照片由人工向厂家确认，不推定只是旧批次文字问题。','纠正W/VA等价及厂家已整改的无证据解释');
qa(1011,'逆变器应匹配制氧机额定电压、实际功率、启动要求及说明书指定的波形，不能统一用额定数值乘3就认定兼容，也不能混用W和VA。请提供机器铭牌与逆变器完整规格，由人工核对厂家要求后确认。','撤除错误乘法与通用三倍功率选型');
qa(838,'dB(A)表示采用A计权的声级。只写dB时需要确认计权方式和测量条件，不能直接得出相同数字的dB(A)听起来更安静。比较设备噪声应看同一计权方式、距离和工况下的数据。','撤除同数值dBA更安静的错误比较');
qa(845,'SN通常是产品序列号，用于识别或追溯设备，不能仅凭有无SN判断是否属于医疗器械。医疗用途和注册信息需要核对具体产品名称、型号及相应证件。','SN不等于医疗注册证明');
qa([831,832,833,855],'关于FDA、CE或其他证件，请提供当前商品的完整型号和需要核对的认证名称，由人工提供对应证书及适用范围。不能用品牌有出口业务代替该型号的有效证件，也不能在未核实前承诺具备认证。','证书核实取代出口即可解释所有认证的断言');
qa([422,490,851,849],'连续运行时长应以具体型号说明书和机身警示为准，不能统一承诺24小时不停机。若标签写明不建议24小时运行，请不要忽略；可提供型号与标签照片，由人工向厂家核对。依赖持续用氧者应提前与医生安排适合连续供氧及备用的方案。','不以营销话术覆盖机身连续使用警告');
qa([420,790],'库存放置时间不能单独证明设备一定正常或一定损坏。请提供型号、生产信息和实际异常表现，按说明书完成使用前检查；需要时由人工核实检测，不能保证长期库存永远不影响性能。','撤除库存永久不影响性能');
qa([473],'遥控器有效距离受具体型号、方向、遮挡和电池状态影响。请先核对对应型号说明书；失灵时可检查电池安装及是否有遮挡，不统一承诺2米或18米。','相互冲突遥控距离不跨型号承诺');
qa([574,575,576,577,578,580,581,594,596,597,598,599],'噪声感受因人和使用环境而异，不能用未展示的评价截图代替实测，也不能保证不会影响睡眠。可查看当前商品真实评价，并核对具体型号的同条件噪声参数；对声音敏感请先向人工确认适用情况。','去除缺失评价图及不会影响睡眠保证');
qa([793,794,795,796,824,868],'请说明声音出现时机、是否突然变大及有无报警，并提供型号和短视频。正常工作声与异常噪声需要结合实际情况判断，不能直接让您适应，也不能保证不会影响睡眠。请保持机器稳固和通风，不用泡沫或布覆盖消音。','噪声投诉不直接判正常/要求适应');
qa([768,797,826],'测量差异需要同时核对制氧机型号、工况、测氧仪量程与校准状态及采样方法。不能只因读数与宣传不一致就认定仪器不适用或机器正常。请提供测量过程和设备信息，由人工按该型号检测要求核实。','不以测量差异为由直接否定测量或保证合格');
qa([672,702,703,843],'分子筛制氧机通常不需要另外添加制氧剂，但不代表没有耗材或无需维护。过滤器、吸氧管等应按具体机型及配件说明书检查、更换；湿化是否需加水也应按该型号操作。','消除无需制氧剂被泛化为无耗材');
qa([754,800,886],'分子筛制氧机利用空气分离获得富氧气体，不是从机内储存的氧气持续释放，也不能把输出描述为100%纯氧。具体出口浓度与流量应以该型号额定参数及检测结果为准。','纠正纯氧/封闭内循环误解');
qa([303,332],'分子筛制氧通常利用吸附过程分离空气中的部分氮气，膜分离则利用不同气体透过膜的差异获得富氧气体。两者不能用“氮分子太大过不去”或膜会识别氧气开门来解释；是否适合用氧应核对产品实际额定参数与医生要求。','撤除错误筛孔/识别式原理比喻');
qa([888,1045],'请先说明用于居家还是外出、医生要求的供氧方式和流量，以及正在考虑的完整型号。我们再按具体产品参数核对，不能仅凭一张未展示的对比图或外部链接决定适用机型。','将只有链接的选型回复改为必要需求收集');
qa([504,443,460,461,462,463,464,465,466,467,468,469,483,484,485,486,557,558,559,560,561,562,563,638,701,1062],'请提供机器铭牌上的完整型号，以及想操作的功能或遇到的问题，再由人工匹配该版本说明书或教程。当前文字知识未附可核实的完整图示步骤，不应要求您照一张未展示的图片操作；请勿强行拆装。','补齐纯图片指代/没有步骤的教程答复');
// 已过期活动与不应独立触发的内部记录：可恢复停用，不删除。
off([66,118,160,162,527,919,921,1959],'内部/临时过期/生成失败记录不适合作为常驻买家问答');
// 确定的文字和上下文修正。
replace(279,'不适用','不使用','修正不使用的错字');
replace(745,'卡主','卡住','修正卡住错字');
for (const i of [261,262,263,264,265,266,267,288,320,321,322,346,349,350,351,352,353,354,355,356,357,358,359,360]) {
  if (!cards[i].title.includes('功率')) continue;
  const txt=body(current(i)); const model=cards[i].title.split('/').at(-1);
  change(i,{content:[{content:txt.replace(/^Q:[^\n]*/,`Q:${model}的额定输入功率是多少？`)}]},'功率问题补足语义，不改参数数值');
}
for(const i of [187,258,291,972]) {
  const txt=body(current(i));
  change(i,{content:[{content:txt.replace(/^Q:[^\n]*/,`Q:${cards[i].title.split('/').slice(2).join(' / ')}`)}]},'恢复斜杠分隔导致丢失的型号上下文');
}
for(const i of [1935]) replace(i,'纯正玄波','纯正弦波','纠正逆变器波形OCR错字');
// 商品自动学习：逐句清理已有明确政策冲突，不改变SKU范围或编造缺失参数。
const productRewrites=[];
for(let i=0;i<cards.length;i++) {
  if(cards[i].type!=='PRODUCT') continue;
  let txt=body(current(i)); const original=txt;
  txt=txt.replace(/HEAP/g,'HEPA');
  txt=txt.replace(/杜绝氧燃隐患/g,'使用时仍须远离明火、吸烟及其他火源，阻燃材料不能消除火灾风险');
  if(txt!==original) {change(i,{content:[{content:txt}]},'修正确定的OCR错字或绝对防火保证');productRewrites.push(i);}
}
// 1087 长文保留操作注意事项，替换冲突的费用和拆封政策段落。
{
 const txt=body(current(1087)); const start=txt.indexOf('### 退换货、质保、维修特别说明'); const end=txt.indexOf('### 特殊注意事项');
 if(start<0||end<start)throw Error('1087 段落保护失败');
 change(1087,{content:[{content:txt.slice(0,start)+'### 退换货、质保、维修特别说明\n本店已确认支持7天无理由退货，医疗款拆封不作为直接拒退理由；30天内不合适支持换款、质量问题包退。家用/医用整机1年、压缩机5年；充电便携机整机2年、电池1年。具体订单、商品状态、配件政策及所有费用事项请由人工核实，不自动承诺扣费、折旧费或费用全免。\n\n'+txt.slice(end)}]},'以既有拍板政策替换商品学习中的拆封不退和自动费用承诺');
}
// 自动学习来的保价句：仅移除承诺所在句/项目，不动其他产品信息。
for(let i=0;i<cards.length;i++) {
 if(cards[i].type!=='PRODUCT')continue;
 const txt=body(current(i));
 if(!/买贵补差|全年[最底低]*价|保价30天|30天保价/.test(txt))continue;
 const lines=txt.split('\n').map(line=>/买贵补差|全年[最底低]*价|保价30天|30天保价/.test(line)?line.replace(/[^。；\n]*?(?:买贵补差|全年[最底低]*价|保价30天|30天保价)[^。；\n]*(?:[。；]|$)/g,'价格、活动及保价需由人工核实，不作自动承诺。'):line);
 change(i,{content:[{content:lines.join('\n')}]},'清除商品学习重新带回的保价承诺，其他参数不变');
}
// 成批审稿后的逐题细化：保留能回答问题的具体事实，避免只剩泛化转人工。
qa([23,24],'流量档位和氧浓度是两项指标。部分1L/2L机型在超出额定制氧流量后，虽然出气量更大，氧浓度会下降；不能把最大可调流量当作保持额定浓度的流量。请核对具体型号的流量—浓度表，按医生要求选用，不要仅凭档位数字判断。','保留流量与浓度的实际解释，不猜内部混气结构');
qa(28,'宣传值与显示值需要结合具体型号、设定流量及说明书允许范围核对。若该型号明确标示93%±3%，90%和96%是该范围两端，不等于所有型号或所有档位均适用。请提供铭牌、运行档位和显示照片，由人工核实；不能仅凭达到90%就保证个人治疗效果。','准确回答宣传96%与机器显示90%的差异');
qa(57,'目前店铺记录的常规开具方式为发票；如您需要单独收据，请提供订单和用途，由人工财务确认是否可开。发票能否满足您的报销或凭证要求，也请向接收单位确认。','保留发票常规流程，不宣称法律上完全替代收据');
qa(64,'弥散制氧终端不是独立制氧主机，需要与匹配主机配套。请先核对订单购买项及现有主机型号，避免只买终端后无法使用；如果买错，可通过订单申请售后，由人工确认处理。','恢复弥散终端购买问题的实际语义','只买弥散制氧终端能单独制氧吗？');
qa([104,105],'如果A1L订单写9L而收到的标识是7L，请提供订单规格、铭牌和外包装照片，由人工核对版本与出库记录。不能直接判断只是新版或保证效果相同；如确有错发，再确认换货等方案，补偿及费用另由人工核实。','型号不符先核实，不能只回复费用');
qa(127,'不能把雾化口直接当作吸氧口。压缩空气式雾化通常用空气驱动，但具体设备的驱动气源和操作方式须看型号说明书。请提供完整型号，核对制氧口与雾化口标识后使用；吸氧需求应接指定吸氧接口。','纠正草稿误归到发货时效，恢复雾化接口问题');
qa(129,'雾化是把液体形成细小雾滴，通过适配组件供人吸入的过程。具体原理和颗粒性能取决于设备型号；是否适合所用药物、剂量及疗程须遵医嘱，不承诺比其他给药方式更快或疗效更好。','保留雾化基础解释');
qa(130,'机器寄回后如还未登记，请提供订单、寄回单号和故障说明，方便人工匹配设备与售后记录。之后寄回前请先确认当次售后地址及登记方式；是否已签收和完成处理需查询实际记录。','恢复寄回登记语义，不混同催退款');
qa([214,233],'雾化不出雾或断断续续时，请提供型号、雾化杯型号及当前现象。可按对应说明书检查管路连接、杯体装配和药液是否在该组件要求的容量范围内；不要自行加药、稀释、改用清水吸入或拆掉过滤器试机。仍异常请联系人工，药物使用问题请咨询医生。','保留雾化专项排查，不给统一加药剂量');
qa(330,'鼻吸管材质需要核对该配件包装或说明书，现有资料同时出现硅胶和PVC，不能跨产品统一认定。请提供配件名称或包装照片，由人工确认；清洗与更换也应遵守该配件的一次性或可重复使用标识。','材质冲突明确核实，不用清洁回答替代材质问题');
qa(427,'现有店铺资料记录为湖南工厂发货、无实体门店；如需到店或自提，请先向人工确认，勿直接前往。发货及到达时间需结合订单和收货地区查询，不能保证湖南省内次日到。','保留实体店答案，撤除保证次日到');
qa([430,431,432],'退回商品是否齐全需要核对实际签收、验货及原订单清单。请提供订单和退回单号，由人工说明具体缺少什么并协商处理；自动回复不代表已经拒退、关闭售后或扣款。','退货缺件与赠品发货区分处理');
qa(470,'请按该型号流量调节旋钮的标记和说明书缓慢调整到医生规定的流量，读数方法也以该流量计说明为准。不要固定转24圈或先开到最大再试；不确定操作方向时，请提供型号和流量计照片。','保留流量计操作问题，不当作报警故障');
qa(476,'用氧流量与时长请按医生方案执行。如果文字说明不方便理解，请说明具体型号和卡在哪一步，可请家人协助阅读对应说明书或向人工索取适合的教程，不要自行猜测档位。','用氧教程理解困难提供可操作替代');
qa([562,563],'C1/A1使用时不要在底部垫泡沫、覆盖布料或堵住进出风口，应放在符合说明书要求的平稳通风位置。请让实际使用者也了解这项注意事项；如已发生异常发热或报警，停止继续试机并联系人工。','保留已有明确通风提醒，不误当图片教程');
qa(564,'吸入气流偏凉时，请先核对设备允许的环境温度和当前使用条件，不要自行给氧路加热、加热湿化水或随意改换面罩。若鼻腔不适持续，请向医生确认合适的接口和湿化安排，同时提供型号供人工核对。','回答冬季偏凉问题，不保证换面罩变暖');
qa([582,758,778],'气流冲鼻或干燥不适时，请先确认机器型号、当前档位和所用接口。不要自行降低医嘱流量或随意改装湿化装置；是否改用面罩需核对机型兼容性并咨询医生，脉冲设备尤其不能任意换接口。','针对出气冲/干燥提供核对步骤');
qa(656,'维修登记需要能够匹配订单和后续寄回信息。您可先提供订单或购机凭证及故障说明，再与人工确认寄回所必需的信息和地址；不要发送无关敏感资料，不会用自动话术认定您失联或放弃设备。','寄修前登记不混同长期未取回');
qa(663,'请提供机器完整型号、现有过滤器标识及清晰照片，由人工核对配件版本。仅在说明书允许用户拆取且断电的情况下取出拍照，不确定时先拍外部位置，不必强行拆卸。','保留过滤器配型步骤');
qa(665,'请先断电，拍下旧过滤器、新过滤器及安装位置，由人工核对型号和密封圈情况。不能在未看到实物前认定旧胶圈一定粘在机上，也不要强行撬取或硬装不匹配配件。','安装不上不直接推断密封圈原因');
qa([672,702,703],'过滤器、过滤盒或过滤棉用于拦截进入设备的灰尘，是需要维护的部件。检查和更换周期应按具体型号说明书及使用环境执行，不能跨型号统一用100—1000小时的区间；未标明可水洗的部件不要水洗，也不要去掉过滤器运行。','保留过滤部件作用及维护问题');
qa(692,'维修费用请让人工结合实际检测项目逐项说明，您确认方案后再安排相应处理。更换哪些部件以维修记录为准，不能以“相当于全新机器”代替项目说明，也不能预先承诺所有部件换新。','恢复维修费贵的咨询重点');
qa(701,'请提供机器完整型号及过滤器外观的清晰照片，尽量拍到整体与积尘位置。需要取出时先断电，并仅按说明书允许的方式操作；照片可用于初步核对，不能单凭照片完成性能检测。','直接说明需要哪种照片，去掉缺失图示指代');
qa(742,'现有售后资料记录中国大陆地区可申请返厂保修。请提供具体型号、订单及所在地，由人工核对对应保修范围和维修方式；“全国联保”不等于任何网点均可修，也不代表全质保期往返运费都自动全免。','保留区域/返厂信息，费用按既有人工政策');
qa(754,'过滤器及后盖应按该型号说明书正确安装后使用，不要为增大进气或降温拆掉过滤器运行。机器需要从周围空气进气，安装时还要保持进出风口畅通；不确定装法可提供型号和照片。','直接回答后盖安装，纠正内部循环说法');
qa([797,826],'噪声读数需要比较相同计权方式、距离、机器档位和背景噪声条件。家庭环境与检测条件不同可能影响结果，但不能因此直接认定超标读数无效或机器正常。请提供型号、测量设备和过程，交人工核对对应检测资料。','纠正草稿将噪声检测误写成测氧仪');
qa(843,'机器一次可连续运行多久，应按具体型号说明书和机身警示确认，不能统一承诺24小时。长期使用还需要按说明书维护过滤器等部件；设备寿命不能仅根据保修年限推算。请提供型号核对。','区分连续运行、寿命和耗材');
qa(874,'现有资料中1SW与Q1W都按额定1L级机型介绍，1SW另列有紫外功能、Q1W未列该项。请以当前商品版本确认功能，不将紫外功能等同于医疗疗效；是否满足吸氧需求仍需核对医生要求。','保留明确款式差异，去掉按轻微缺氧推荐');
qa(970,'1SW与2SW主要区别是额定制氧能力：现有资料分别按1L/min与2L/min的额定工况介绍，不能把最大可调档位当作额定输出。请核对当前版本流量—浓度表，再按医生明确的用氧要求选择，不能只按感觉缺氧就推荐2SW。','保留1SW/2SW参数差异');
qa(954,'比较不同“升数”时，应看说明书中在规定氧浓度下的额定输出流量，而不是只看最大可调流量或脉冲档位。额定1L、3L、5L、10L代表不同供氧能力，并不直接对应轻、中、重病情；选型应匹配医生要求。','保留升数区别，不只回复就医');
qa(979,'无级调节指在设备允许范围内连续、平滑地调节流量，而不是只在几个固定档位之间切换。具体范围和读数方式以型号说明书为准，使用时仍应调到医生规定的流量，不是凭舒适程度随意调整。','保留无级调节定义');
qa(1005,'制氧机提供富氧气体；CPAP主要提供持续气道正压，帮助维持气道开放，两者用途不同，不能互相替代。是否需要一起使用应由医生决定，并核对双方型号、供氧接口和兼容要求，不能任意接上就保证效果更好。','保留CPAP与制氧机功能区别');
qa(1011,'稳压器需匹配机器铭牌电压、输入范围、额定负载和启动要求，不能一律用功率乘3或混用W与VA判断。请提供制氧机与稳压器的完整规格，由人工按厂家要求核对；使用稳压器不能替代对异常电源的检查。','稳压器与逆变器分开，不泛化波形要求');
qa(1055,'儿童是否需要吸氧或雾化，应先由医生评估，并确认设备和配件的适用人群。吸氧的流量、时长与雾化药物、剂量均须遵医嘱，不能统一按3岁或6岁划线。使用时需要成人照看；不能清楚表达不适的孩子尤其需要医生安排监测。','同时回答儿童吸氧及雾化');
qa(1062,'请先说明居家还是外出使用、医生规定的供氧方式和流量，以及正在考虑的机型。选型需要逐项核对额定流量—浓度、接口与使用条件，不仅按一张对比图或疾病名称选择。','选型问题不误当操作教程');
qa(1065,'单次能否吸1小时应按照医生为您制定的用氧方案，不能以血氧达到95%就自行停氧，也不能统一建议每天三次各30分钟。机器允许的连续运行时长须另按具体型号说明书确认。','按原聊天问题补足单次1小时的回答','这款制氧机能一次吸氧1小时吗？');
// 已变更的SHOP问题去除内部序号/处方答案提示，补足会因斜杠丢失的型号。
const naturalQuestions={20:'从哪里发货、发什么快递，什么时候发出？',21:'从哪里发货、发什么快递，什么时候发出？',55:'提交开票信息后怎样确认登记状态？',61:'赠品或配件补发是否已登记？',62:'收到的物品疑似错发或漏发怎么办？',63:'补寄需要提供哪些收件信息？',69:'退货时赠品没有寄回怎么办？',73:'退货后退款进度怎么查？',74:'申请退款会影响信用吗？',83:'质量问题退货应该填写什么原因？',85:'疑似发错货，售后原因怎么填？',86:'功能或性能异常，售后原因怎么填？',90:'想把换货改成退货怎么办？',92:'吸氧没有改善，需要换更大流量的机器吗？',94:'换货申请的进度怎么查询？',96:'换货方案是否已批准？',131:'退回检测未复现故障怎么办？',132:'多次维修后仍故障，怎样确认原因？',133:'泡沫有痕迹能证明使用不当吗？',134:'110V机器疑似接错电源损坏怎么办？',135:'机器底部曾垫泡沫，故障该怎么处理？',172:'个人发票抬头如何确认？',246:'机器冒烟或起火了怎么办？',364:'不再换货时怎样处理原售后申请？',377:'晒单赠品是否已登记？',430:'退货的赠品可能没寄齐怎么办？',431:'退货缺少物品会扣款吗？',432:'退货缺件会被拒绝吗？',476:'看不懂用氧或机器操作说明怎么办？',529:'一定要先撤销投诉才能处理售后吗？',530:'我的问题会如何反馈和处理？',537:'这个问题能否由人工协助？',540:'问题反复未解决，我很着急怎么办？',541:'我需要持续吸氧，机器坏了怎么办？',542:'持续用氧期间担心设备故障怎么办？',543:'备用供氧的说明看不懂怎么办？',548:'如何反馈产品使用建议？',549:'投诉问题的处理进度怎么确认？',550:'反映的问题是否已经整改？',552:'配件质量问题如何处理？',615:'看到维修报价后不想修了怎么办？',616:'维修报价后还没确认处理方案怎么办？',656:'寄修前为什么需要登记信息？',692:'维修费贵，怎样核实维修项目？',699:'用于养鱼后出现故障，如何申请售后？',701:'过滤器需要拍哪些照片供核实？',706:'寄修机器清洁事项和费用如何确认？',750:'取下过滤器后机器仍不制氧怎么办？',767:'刚收到的过滤器有脏污怎么办？',802:'制氧机耗材费用怎么确认？',825:'机器噪声大，能否提供长管方案？',900:'赠品申请的处理结果如何确认？',902:'如何联系人工处理售前问题？',923:'如何联系人工处理售后问题？'};
for(const [n,question] of Object.entries(naturalQuestions)){const i=Number(n);const txt=body(current(i));change(i,{content:[{content:txt.replace(/^Q:[^\n]*/,`Q:${question}`)}]},'问题改为买家表达，避免内部作业语');}
for (const [i,x] of [...edits]) {
 if(x.after.type!=='SHOP'||!x.after.ifOpen)continue;
 let question=q(i);
 if(naturalQuestions[i])continue;
 if([50,86,483,484,561,563,638].includes(i))question=cards[i].title.split('/').slice(2).join(' / ');
 else if([938,939,940,941,942,992,993,995,996,997,998,999,1000,1001,1025,1026,1027,1028,1029,1030,1031,1032,1033,1034,1035,1036,1037,1038,1058,1059,1060].includes(i))question=cards[i].title.split('/').slice(2).join(' / ').replace(/[→➝].*$/,'').replace(/[？?][35]升$/,'？').replace(/选几升制氧机？5升$/,'如何选择设备？');
 else continue;
 change(i,{content:[{content:body(current(i)).replace(/^Q:[^\n]*/,`Q:${question}`)}]},'恢复完整型号/疾病问题，去掉问题中预埋的升数处方');
}
// 第二遍正文交叉检查：处理其他入口中重复出现的同一风险。
qa([44,45],'机器出口氧浓度不等于人体实际吸入氧浓度，不能按固定25%或按舒适程度选择档位。请按医生规定的供氧方式、流量和时长使用，并核对该型号在所需流量下的氧浓度。','其他入口同样去除凭舒适度调档');
qa(87,'如果产品不符合您的需要，可以说明您希望退货、换货还是继续排查，并提供对应订单，由人工核实适用的售后方案。我们尊重您的选择，不要求您继续购买或更换品牌。','不以买别家打发售后诉求','对产品不满意，如何申请售后？');
qa(156,'如需参加晒单活动，请先向人工确认对应订单的活动资格和当前规则。评价请如实描述使用体验，不必作好评或疗效保证；提交所需凭证后，还需人工确认登记及发货状态，不统一承诺1—2天寄出。','修正评价错字并撤除未查询赠品时效');
qa([168,169,180],'氧气袋的充装时间、储存要求及可使用时长，需要核对袋体规格、允许充装方式及实际输出流量。容量除以流量仅是理论估算，不能保证储存72小时或实际持续使用42分钟；请按产品说明书使用，不把普通氧气袋当作可靠的生命支持备用设备。','氧气袋理论时间不作实际供氧保证');
qa(181,'积水器用于收集管路中的积水，不能保证任何情况下水都不会进入鼻端。请按该配件说明书安装并检查积水，勿在使用者吸氧时随意拆开；出现喷水或反复积水请提供型号交人工排查。','撤除积水器绝对防喷水保证');
qa(198,'喷气持续时间受具体规格、阀门和按压方式影响，不能只凭持续时间判断缺量，也不能直接排除容量异常。请提供规格、批次及使用经过，由人工核实；不以“氧气成本低”证明一定足量。','不以成本或大口径猜测排除缺量');
qa(220,'可按压次数和持续时间受规格及每次按压方式影响，应以该产品说明为准，不统一保证90次、180次或90秒。出现胸闷、明显气促等症状，不要把便携氧气罐当作急救替代，应及时就医。','撤除固定次数与胸闷应急自疗');
qa(237,'雾化配件每次使用后的清洗、消毒和干燥方法，以及更换周期，应按该套配件说明书执行；一次性配件不要重复使用。不能将“每次清洗”和“每月清洗”混为一谈，也不要自行用未认可的方法消毒。','纠正雾化清洁周期自相矛盾');
qa(272,'估算耗电量可用实际平均功率W÷1000×运行小时数，结果为kWh（度）。例如实际平均功率700W运行1小时约0.7度；铭牌额定功率不一定等于实时平均功率。具体电费按当地实际电价或电表记录计算。','保留耗电公式，去除臆定全国电价');
qa(414,'10L机型的额定流量和对应氧浓度应核对具体型号说明书，不是所有标10L的设备都能在每一档保持同一浓度。双人同时使用还需确认设备是否支持独立、可控的两路输出，并满足每个人的医嘱，不能仅凭总流量10L就保证适用。','撤除双人使用的普遍保证');
qa([433,440],'是否超过退换期限，需要核对订单签收时间、问题性质和对应服务政策。请提供订单与故障说明，由人工确认退、换、修等可行方案；未查询前不能认定已经超期或只能维修。','去掉默认订单超期和绝对拒退');
qa(521,'您指出的页面信息缺失或不清楚，需要结合具体商品与版本核对。请提供页面截图和关注的功能，由人工确认实际配置；涉及使用限制和安全提示，也应明确告知，不能用“页面只写优点”代替解释。','正面处理信息缺失而非推脱');
qa([534,535,539,553],'抱歉这件事给您带来困扰。请提供订单和仍未解决的问题，由人工核实原因及处理方案；是否已登记、反馈或完成需以实际记录为准。','清理其他入口的假登记/先认责/满意保证');
qa(618,'维修可能涉及检测、配件处理和维修后测试，具体耗时需要查询该台设备的实际进度。请提供订单或维修单号，由人工确认当前环节和预计安排；维修后测试不能保证以后绝不再发生故障。','撤除修好绝不再故障及未经执行催办');
qa([646,648],'是否属于使用不当应依据具体使用条件、说明书及实际检测结果，不能用类比直接排除质量问题。请提供型号、故障经过和使用环境，由人工核实并说明判断依据。','删除汽车下水类比及无依据归责');
qa(649,'非本店购买的设备可先提供型号、购机凭证和故障说明，由人工确认可提供的维修服务与保修起算依据。不能统一按出厂日期保1年，也不自动确认费用由谁承担。','非官方购买不编造统一保修规则');
qa([651,658],'没有订单号时，可以先提供购买平台、店铺、时间及现有购机凭证或机器型号，由人工协助核对。请遮挡无关个人信息；在核实前不直接拒绝协助，也不默认按付费维修处理。','缺订单提供替代核实路径');
qa([673,684],'照片或视频有助于初步了解问题；不方便提供时，可先说明型号、故障出现经过、显示及报警情况，再由人工确认是否需要进一步检测。是否寄回及费用应核实后说明，不以不拍照直接认定买家承担费用。','取消无法拍照等于承担费用');
qa(680,'请说明机器什么时候开始异常、当时在做什么操作，以及现在的显示、声音或出气情况；有报警代码也请一并提供，方便判断下一步排查方向。','先采集现象，不预设已经被买家弄坏','故障原因暂不清楚，需要提供什么信息？');
qa(695,'维修更换的零件及旧件处理方式，应由人工结合维修记录和对应服务约定说明。请提供维修单号核实，不能在未查看记录前保证已经换新或直接认定旧件必须回收。','旧件政策待确认，不假称实际已换');
qa(697,'是否停产、还有没有配件和能否维修，需要按完整型号及实际库存核实，不能只因使用超过5年就认定无法修。请提供型号及故障情况，由人工确认维修或其他可选方案，费用另行核实。','不把过保直接等同停产缺件劝换新');
qa(700,'没有原包装时，请先联系人工确认该机型的安全寄回要求，并向承运方咨询合适的防护包装。按说明书处理湿化水和电池等部件，确认运输方式后再寄出；责任与费用需结合实际情况核实，不预先认定一律不保修或已加急。','保留包装帮助，撤除免责和虚构加急');
qa(719,'遥控器是否随附电池及所需规格，请核对当前商品清单和遥控器电池仓标识；现有部分资料列为2节7号电池，但不宜跨型号套用。电池运输要求需由承运方确认，不能一概说所有电池不能上飞机。','去除不实航空运输理由，保留型号核对');
qa(766,'吸氧管有明显异味或引起不适时，不要直接认定是正常材质气味而继续使用。请提供配件包装、型号及出现情况，由人工确认材质和处理方式；清洗须遵守配件说明，补发及费用另由人工核实。','统一材质冲突与异味安全，撤除自动补发');
qa(770,'是否有医疗器械注册信息需要核对具体产品名称和完整型号，不能仅因不是药品就回避医疗器械证件问题。请提供商品链接或铭牌，由人工核实对应注册/备案资料及适用范围。','器械不等于无需医疗器械注册核对');
qa([772,773],'管路水珠可能与湿化水位、温差或连接情况有关，但不能直接认定一定正常。请提供型号、水位和管路照片，按说明书检查积水处理方式；不要自行用最大档吹水或随意更换面罩。反复喷水、气路受阻或使用不适请联系人工，必须持续用氧者先按医生方案保障供氧。','其他水珠入口撤除最大档吹水及无故障保证');
qa(798,'“静音”不代表无声，也不能保证不影响睡眠。噪声比较需要核对具体型号及相同测量条件，不以“40分贝属于国家静音标准”作通用解释。请描述实际声音和使用环境，由人工核实是否异常。','撤除未证实国家静音界限');
qa(815,'鼻吸管变色或变脏时，请按配件说明书核对是否需更换，并提供照片和使用情况。不能仅因水箱水清澈或只有局部变色就认定是衣物染色、不影响安全；不要继续使用明显污染或引起不适的管路。','不以清水/局部变色推断管路安全');
qa(819,'通电后屏幕不亮，请先提供型号、是否有声音或报警及发生经过。按该型号说明书检查外部电源连接；不要反复快速拔插电源强制重启。仍异常请联系人工；正在依赖持续供氧时，应先按医生备用方案处理。','撤除通用快速断电重启');
qa(840,'现有店铺资料以返厂维修为主要方式。是否有当地网点或上门服务，请提供所在地与型号由人工确认；不以未经核实的低故障率解释服务布局，也不保证返厂必然比其他方式更专业。','售后渠道说明不靠无证据优越性');
qa(847,'使用时应保持进出风口畅通、机器不被覆盖，并遵守该型号环境要求。即使有过热保护也不能忽略异常发热、焦糊味或报警；出现这些情况请在安全前提下停用并联系人工核实。','保护功能不等于无过热风险');
qa(873,'如果还在考虑，可以先确认医生的用氧要求和您关心的功能，再核对合适型号。请按实际需要决定是否购买，不用未核实的销量或“治好多少人”作为购买依据。','去掉30万人解决缺氧的未经证实医疗广告','还在考虑是否购买制氧机怎么办？');
qa(879,'是否属于医用产品，应看具体型号对应的注册用途和说明书，不能仅按家用名称或升数判断。额定流量、对应氧浓度及报警配置应逐项核对；医用身份不代表适合所有病情，仍须匹配医生要求。','不把3/5L自动等同医用96%以上和治疗效果');
qa(883,'氧浓度下降可能需要核对设置、环境、维护状态或设备故障，不能直接视为正常保护。请提供型号、当前流量、显示和报警情况，由人工按该型号要求排查；不要因没有其他症状就忽略持续异常。','浓度下降不一概判正常保护');
qa([901,913,916,933,934],'抱歉让您等待。查询订单或售后处理需要人工确认，请在当前平台会话申请人工，并提供订单和问题说明。自动回复不代表已经登记或约定回电；如需后续联系，请与人工确认方式和时间。','清理假真人离座/已登记和次日必回承诺');
qa(922,'中央或弥散制氧、批量采购需要专人核对方案。请先说明使用场景、地区及计划数量，并在当前平台申请人工；如确需电话沟通，再与人工确认必要的联系方式。','清除沟通xx占位符，先收集业务需求','中央/弥散制氧或批量采购如何咨询？');
qa(924,'建议通过当前平台订单页面提供的付款方式完成交易，保留订单和付款凭证。若需其他采购方式，请先在平台会话联系人工核实，不直接向未经确认的个人账户付款。','不臆造平台对公转账规则');
qa([956,975],'负离子功能属于设备的附加功能，不等于氧疗，也不能据此保证杀菌、治疗疾病或改善血氧。具体是否配备、如何开启及相关性能，请以该型号说明书和有效检测资料为准。','未证实负离子抗菌/医疗效果不自动传播');
qa(983,'现有1SW/2SW资料的“双重抑菌”涉及紫外功能和水箱材料，但作用范围及效果需核对该版本说明书和检测依据，不能等同整个气路无菌，也不能替代规定的清洁、更换。','抗菌宣传限定范围，避免无菌保证');
qa(989,'高海拔使用必须核对具体型号的额定海拔范围及该条件下的输出性能，不能保证所有机型在4500或5000米仍可正常满足用氧。请提供使用海拔和医生要求，由人工核对厂家资料；有明显高原不适应及时就医，不等待升级购买。','撤除任意高海拔可用及见血氧90即可的保证');
qa([991,994],medical,'多人轮流或健康保健不直接决定需要几升');
qa(1018,'如果正在医院吸氧，请直接向医护人员确认出院后的居家用氧处方，包括供氧方式、流量和时长。医院当前流量可以提供给医生核对，但不能仅照搬到家用机型或自行读取后决定购买。','医院当前流量不是自动居家处方');
qa(1020,'如方便，请提供最近测得的血氧饱和度、测量时是在静息还是吸氧状态，以及医生是否已有用氧建议。读数用于了解情况，不能单独决定购买升数或自行调档。','纠正血氧浓度术语并补足测量上下文','选型时需要提供哪些血氧测量信息？');
qa(1063,'过滤棉价格需要核对对应机型及配件规格。请提供机器完整型号或过滤棉照片，在平台会话申请人工确认适配型号与当前价格。','聊天学习费用类同样按人工政策','过滤棉一张多少钱？');
qa(1064,'部分保健机型调大流量后，氧浓度会降低；最大可调流量不等于在额定浓度下的制氧能力。请以该具体型号的流量—浓度表为准，不要把更大出风量当作更多高浓度氧气。','聊天学习清理错字及固定混气原理','调大档位出风量变大，就代表制氧量更大吗？');
qa(1066,'分子筛制氧机从周围空气中分离获得富氧气体，不是把所有其他气体去除后只剩100%纯氧。具体氧浓度和输出流量以该型号说明书为准。','聊天学习同样纠正纯氧原理','制氧机的制氧原理是什么？');
qa(1116,'包装内吸氧管数量需要按当前订单SKU和装箱清单核对。若商品描述与实物数量不一致，请提供订单及收到物品照片；额外领取或补发资格、频率和运费由人工确认。','聊天学习不承诺每三月付邮领取','包装吸氧管数量和商品描述不一致怎么办？');
qa(1118,'过滤棉应按对应机型说明书检查和更换，不能仅按鼻吸管活动周期推定。是否赠送或需购买、相应费用和领取条件请由人工核对订单与活动；制氧无需额外制氧剂不代表无耗材。','聊天学习同样清理无耗材/固定付邮领取','过滤棉多久更换，能否免费领取？');
// 已有参数保留，只撤掉型号卖点中的普遍疗效与睡眠保证。
for(const i of [944,945,947,950,978,980,981,982,985,986]){
 let txt=body(current(i));
 txt=txt.replace(/适合(?:轻中度|中重度)缺氧患者长期家庭氧疗使用哦～/g,'是否适用请按医生明确的用氧要求核对。')
  .replace(/满足中重度缺氧人群长期家庭氧疗需求/g,'是否满足用氧需求须按医生要求核对')
  .replace(/适合轻中度缺氧人群长期家庭氧疗/g,'是否适用须按医生要求核对')
  .replace(/夜间运行安静，不打扰休息💤，适合睡眠浅的用户。/g,'噪声感受因环境和个人敏感程度而异，不保证不影响睡眠。')
  .replace(/24小时稳定供氧/g,'连续运行时长按该版本说明书执行')
  .replace(/支持双人同时吸氧/g,'双人使用须先核对该版本是否支持及两人的医嘱要求')
  .replace(/✅ 适用范围广：术后保健、孕妇、老人、高原、搭配逆变器可车载～/g,'✅ 是否适用于个人用氧、高原或车载，需核对医嘱和该型号规定的使用条件。')
  .replace(/满足长期氧疗需求/g,'是否满足用氧需求须按医生要求核对')
  .replace(/✅ 支持7天免费试用，还送氧气枕🎁/g,'✅ 支持7天无理由退货；费用和赠品活动请由人工核实，不等于无条件免费试用。')
  .replace(/特别适合老人、术后保健、慢阻肺等人群，品质机型，推荐入手！/g,'请按医生明确的供氧要求核对，不能仅按年龄或疾病名称判断适用。');
 if(txt!==body(current(i)))change(i,{content:[{content:txt}]},'保留型号参数和功能，只去掉普遍疗效/睡眠/免费试用承诺');
}
// 模拟验证发现的定向补改：不是按目录名称限定公共安全/借机政策。
qa(987,'德达A1不带雾化，也不带遥控，可使用机身按键操作。此结论仅针对A1；其他型号是否有雾化或遥控应逐款核对，不能按型号中有没有L、W字母推断。','模拟中出现未引用资料支持的L/W泛化，明确不按字母推断','德达A1有雾化和遥控吗？');
qa(544,'目前不提供备用机借用，因此不能安排备用机寄出。如需连续用氧，请提前与医生制定备用供氧方案；现有设备故障请在平台联系人工核实售后。','备用机政策问题改为直接购买/借用咨询','能否提供或借用备用机？');
for(const i of [219,544,813])change(i,{orderStatus:['PRE_SALE','SALE','AFTER_SALE']},'模拟证实未下单无法检索；禁用明火与无备用机政策不依赖订单阶段，仅这3张扩展三阶段');
qa(813,'不可以。请不要用打火机、明火、香烟或火星测试制氧机出来的气体，氧气会助燃，可能造成火灾或烧伤。怀疑出氧浓度异常时，请提供型号、设置及报警情况，由人工按该型号要求安排适用仪器检测；屏幕数值不能一概当作实时浓度检测结果。','完成学习后自然问法仍未引用安全卡，补足打火机问法并防止屏幕即实测的扩写','可以用打火机或明火测试制氧机出来的是不是氧气吗？');
qa(219,'不可以。请不要用打火机、明火、香烟或火星做氧气瓶、氧气罐的助燃测试，可能造成火灾或烧伤。对瓶内气体或容量有疑问，请保留产品信息并联系人工核实，不要自行拆瓶或测试。','氧气瓶安全问法同样明确打火机，不误用制氧机屏幕检测','可以用打火机测试氧气瓶或氧气罐的纯度吗？');
// 问题和标题保持一致，避免旧标题中的“疾病→5升”等处方被再次检索。
for(const [i,x] of [...edits]){
 if(x.after.type!=='SHOP'||body(x.before)===body(x.after))continue;
 const question=body(x.after).match(/^Q:(.*)/)?.[1];
 if(!question)throw Error('SHOP缺少Q '+i);
 const parts=String(x.before.title||'').split('/');
 const title=parts.length>=3?parts.slice(0,2).join('/')+'/'+question:question;
 change(i,{title},'标题同步实际问题，不残留旧处方或错误型号触发词');
}
// 完全重复必须同时满足店铺/SKU、订单阶段、可信标记、时间条件等一致。
const stable=v=>JSON.stringify(v,(_,x)=>x&&typeof x==='object'&&!Array.isArray(x)?Object.fromEntries(Object.entries(x).sort(([a],[b])=>a.localeCompare(b))):x);
const groups=new Map();
for(let i=0;i<cards.length;i++) {
 const c=current(i); if(!c.ifOpen||c.type!=='SHOP')continue;
 const key=stable({text:body(c).trim(),type:c.type,labels:c.labels,believable:c.ifBelievable,include:c.includeCondition,exclude:c.excludeCondition,stages:c.orderStatus,timeliness:c.timeliness,cycle:c.cycleTimeliness});
 if(!groups.has(key))groups.set(key,[]);groups.get(key).push(i);
}
for(const list of groups.values())if(list.length>1){list.sort((a,b)=>String(cards[a].createdAt).localeCompare(String(cards[b].createdAt))||cards[a].id.localeCompare(cards[b].id));off(list.slice(1),'同正文同范围同阶段完全重复；保留原卡 '+cards[list[0]].id);}
const plan=[...edits.values()].filter(x=>stable(x.before)!==stable(x.after)).sort((a,b)=>a.index-b.index);
fs.writeFileSync(BACKUP+'/planned-changes.json',JSON.stringify(plan,null,2));
fs.writeFileSync(ROOT+'/问答优化逐条清单-20260905.md','# 问答优化逐条清单\n\n执行状态以审核报告为准；此文件为可恢复的原位变更清单。574项中1项原本一致，实际写入573张；未改卡片不代表产品事实已经由厂家认证。\n\n'+plan.map(x=>`## [${x.index}] ${x.id} ${x.before.title||'(商品知识)'}\n\n- 原因：${x.reasons.join('；')}\n- 启用：${x.before.ifOpen} → ${x.after.ifOpen}\n- 类型/店铺与SKU范围：不变\n- 订单阶段：${JSON.stringify(x.before.orderStatus)} → ${JSON.stringify(x.after.orderStatus)}\n\n### 原文\n\n${body(x.before)}\n\n### 优化后\n\n${body(x.after)}\n`).join('\n'));
console.log(JSON.stringify({count:cards.length,changes:plan.length,content:plan.filter(x=>body(x.before)!==body(x.after)).length,disabled:plan.filter(x=>x.before.ifOpen&&!x.after.ifOpen).length,byType:plan.reduce((a,x)=>(a[x.before.type]=(a[x.before.type]||0)+1,a),{}),productRewrites}));
module.exports={cards,plan,body,ROOT,BACKUP,stable};
